(3, 'B2.4', 17, 'Arrecadação Tributária RFB: Série Completa 2026', '1. Jan: R$ 368 mi → Jun: R$ 513 mi — crescimento de 39,3% na arrecadação de quota fixa
2. R$ 2,48 bi de apostas de quota fixa · R$ 4,96 bi de loterias no 1S/2026
3. Acumulado jan-mai/2026: R$ 5,89 bi (+85,88% vs jan-mai/2025 — R$ 3,17 bi)', NULL, 'R$ 7,44 bi em 6 meses', CAST('["Jan: R$ 368 mi → Jun: R$ 513 mi — crescimento de 39,3% na arrecadação de quota fixa","R$ 2,48 bi de apostas de quota fixa · R$ 4,96 bi de loterias no 1S/2026","Acumulado jan-mai/2026: R$ 5,89 bi (+85,88% vs jan-mai/2025 — R$ 3,17 bi)"]' AS JSON), 'Fonte: Receita Federal do Brasil; BNLData, mai-ago/2026', 'approved', NULL),
